CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated;
CREATE TABLE public.nickname_warnings (name text PRIMARY KEY, warnings integer NOT NULL DEFAULT 0 CHECK (warnings BETWEEN 0 AND 3), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.nickname_warnings TO anon, authenticated;
GRANT ALL ON public.nickname_warnings TO service_role;
ALTER TABLE public.nickname_warnings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public nickname warning counts" ON public.nickname_warnings FOR SELECT TO anon, authenticated USING (true);
CREATE FUNCTION public.warn_nickname(_name text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE total integer; BEGIN IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501'; END IF; IF char_length(btrim(_name)) NOT BETWEEN 1 AND 10 OR btrim(_name) = '익명' THEN RAISE EXCEPTION 'Invalid nickname'; END IF; INSERT INTO public.nickname_warnings(name,warnings) VALUES (btrim(_name),1) ON CONFLICT(name) DO UPDATE SET warnings = LEAST(3, public.nickname_warnings.warnings + 1), updated_at = now() RETURNING warnings INTO total; RETURN total; END $$;
REVOKE ALL ON FUNCTION public.warn_nickname(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.warn_nickname(text) TO authenticated;
GRANT DELETE ON public.records TO authenticated;
CREATE POLICY "Creators delete race records" ON public.records FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE FUNCTION public.enforce_moderated_record_name() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF EXISTS (SELECT 1 FROM public.nickname_warnings WHERE name = NEW.name AND warnings >= 3) THEN NEW.name := '익명'; END IF; RETURN NEW; END $$;
CREATE TRIGGER enforce_moderated_record_name BEFORE INSERT ON public.records FOR EACH ROW EXECUTE FUNCTION public.enforce_moderated_record_name();